// Check of the active modules' queue (scripts/check_templates.sh): include/active_demo/active.hpp of
// tests/fixtures/active.scaffold.yaml, generated by cpp98. Prints "ok" or the failed check.
#include <active_demo/active.hpp>

#include <cstdlib>
#include <iostream>
#include <vector>

#include <pthread.h>
#include <unistd.h>

using active_demo::ActiveError;
using active_demo::ActiveJob;
using active_demo::ActiveQueue;

namespace {

int failures = 0;

void expect(bool ok, const char* what)
{
    if (!ok) {
        std::cerr << "FAILED: " << what << '\n';
        ++failures;
    }
}

void sleepMs(int ms) { usleep(ms * 1000); }

/// Notes the thread it ran on and returns 42.
class Compute : public ActiveJob {
public:
    Compute() : result(0), ran(false) {}
    void run()
    {
        thread = pthread_self();
        ran = true;
        result = 42;
    }
    int result;
    bool ran;
    pthread_t thread;
};

/// Appends its number to a list.
class Append : public ActiveJob {
public:
    Append(std::vector<int>& list, int n) : list_(list), n_(n) {}
    void run() { list_.push_back(n_); }

private:
    std::vector<int>& list_;
    int n_;
};

/// Sleeps, or waits for a flag.
class Hold : public ActiveJob {
public:
    explicit Hold(volatile bool* go, int ms = 0) : go_(go), ms_(ms) {}
    void run()
    {
        if (ms_) sleepMs(ms_);
        while (go_ && !*go_) sleepMs(1);
    }

private:
    volatile bool* go_;
    int ms_;
};

/// Counts its runs.
class Count : public ActiveJob {
public:
    explicit Count(int& n) : n_(n) {}
    void run() { ++n_; }

private:
    int& n_;
};

} // namespace

int main()
{
    {
        ActiveQueue q(8, 1000, ActiveQueue::block);
        Compute job;
        q.call(job);
        expect(job.ran && job.result == 42, "call runs the job and waits for it");
        expect(!pthread_equal(job.thread, pthread_self()), "call runs on the module's thread");
    }
    {
        std::vector<int> order;
        {
            ActiveQueue q(64, 1000, ActiveQueue::block);
            for (int i = 0; i < 20; ++i) q.post(new Append(order, i));
        }
        bool sorted = order.size() == 20;
        for (int i = 0; sorted && i < 20; ++i) sorted = order[i] == i;
        expect(sorted, "posted calls run in order, all of them");
    }
    {
        Compute late;
        {
            ActiveQueue q(8, 50, ActiveQueue::block);
            q.post(new Hold(0, 200));
            bool timedOut = false;
            try {
                q.call(late);
            } catch (const ActiveError&) {
                timedOut = true;
            }
            expect(timedOut, "call times out");
        }
        expect(!late.ran, "a call given up does not run");
    }
    {
        volatile bool go = false;
        ActiveQueue q(1, 1000, ActiveQueue::error);
        q.post(new Hold(&go));
        sleepMs(20);
        q.post(new Hold(0));
        bool full = false;
        try {
            q.post(new Hold(0));
        } catch (const ActiveError&) {
            full = true;
        }
        go = true;
        expect(full, "overflow error throws on a full queue");
    }
    {
        int ran = 0;
        {
            volatile bool go = false;
            ActiveQueue q(1, 1000, ActiveQueue::drop);
            q.post(new Hold(&go));
            sleepMs(20);
            q.post(new Count(ran));
            q.post(new Count(ran));
            go = true;
        }
        expect(ran == 1, "overflow drop loses the call");
    }
    if (failures) return EXIT_FAILURE;
    std::cout << "ok\n";
    return EXIT_SUCCESS;
}
